// Generator program: compile and run on x86 to output pre-computed flattened weights
// Usage: gcc -o gen_flattened_weights gen_flattened_weights.c && ./gen_flattened_weights >> braggnn.h
#include <stdio.h>
#include <stdint.h>
#include <assert.h>

// Mock gemmini types so braggnn.h can be included standalone
#define SRC_MAIN_C_GEMMINI_TESTUTILS_H
typedef int8_t elem_t;
typedef int32_t acc_t;

#include "braggnn.h"

void flatten_weights(
    int out_channels, int kernel_dim, int in_channels, int patch_size,
    elem_t *weights_4d,
    elem_t *weights_mat) {

  assert(patch_size == kernel_dim * kernel_dim * in_channels);

  for (int outc = 0; outc < out_channels; outc++) {
    for (int krow = 0; krow < kernel_dim; krow++) {
      for (int kcol = 0; kcol < kernel_dim; kcol++) {
        for (int inc = 0; inc < in_channels; inc++) {
          int wmatrow =
              krow * kernel_dim * in_channels + kcol * in_channels + inc;
          // weights_4d[outc][krow][kcol][inc] -> flat index
          int src_idx = outc * (kernel_dim * kernel_dim * in_channels)
                      + krow * (kernel_dim * in_channels)
                      + kcol * in_channels
                      + inc;
          // weights_mat[wmatrow][outc]
          int dst_idx = wmatrow * out_channels + outc;
          weights_mat[dst_idx] = weights_4d[src_idx];
        }
      }
    }
  }
}

void print_array_2d(const char *name, int rows, int cols, elem_t *data) {
  printf("static elem_t %s[%d][%d] = {\n", name, rows, cols);
  for (int r = 0; r < rows; r++) {
    printf("    {");
    for (int c = 0; c < cols; c++) {
      if (c > 0) printf(",");
      printf("%4d", data[r * cols + c]);
    }
    if (r < rows - 1)
      printf("},\n");
    else
      printf("}\n");
  }
  printf("};\n\n");
}

int main() {
  printf("\n// ============================================\n");
  printf("// Pre-computed flattened weight matrices\n");
  printf("// Generated by gen_flattened_weights.c\n");
  printf("// flatten_weights: weights[outc][krow][kcol][inc] -> weights_mat[patch][outc]\n");
  printf("// ============================================\n\n");

  // conv1_weights[64][3][3][1] -> conv1_weights_flat[9][64]
  {
    int out_ch = CONV1_FILTERS, kd = CONV1_KERNEL, in_ch = INPUT_CHANNELS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)conv1_weights, (elem_t *)mat);
    print_array_2d("conv1_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  // conv2_weights[32][3][3][64] -> conv2_weights_flat[576][32]
  {
    int out_ch = CONV2_FILTERS, kd = CONV2_KERNEL, in_ch = CONV1_FILTERS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)conv2_weights, (elem_t *)mat);
    print_array_2d("conv2_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  // conv3_weights[8][3][3][32] -> conv3_weights_flat[288][8]
  {
    int out_ch = CONV3_FILTERS, kd = CONV3_KERNEL, in_ch = CONV2_FILTERS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)conv3_weights, (elem_t *)mat);
    print_array_2d("conv3_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  // nlb_theta_weights[32][64] (treated as [32][1][1][64]) -> nlb_theta_weights_flat[64][32]
  {
    int out_ch = CONV2_FILTERS, kd = NLB_THETA_KERNEL, in_ch = CONV1_FILTERS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)nlb_theta_weights, (elem_t *)mat);
    print_array_2d("nlb_theta_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  // nlb_phi_weights[32][64] (treated as [32][1][1][64]) -> nlb_phi_weights_flat[64][32]
  {
    int out_ch = CONV2_FILTERS, kd = NLB_PHI_KERNEL, in_ch = CONV1_FILTERS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)nlb_phi_weights, (elem_t *)mat);
    print_array_2d("nlb_phi_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  // nlb_g_weights[32][64] (treated as [32][1][1][64]) -> nlb_g_weights_flat[64][32]
  {
    int out_ch = CONV2_FILTERS, kd = NLB_G_KERNEL, in_ch = CONV1_FILTERS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)nlb_g_weights, (elem_t *)mat);
    print_array_2d("nlb_g_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  // nlb_out_weights[64][32] (treated as [64][1][1][32]) -> nlb_out_weights_flat[32][64]
  {
    int out_ch = CONV1_FILTERS, kd = NLB_OUT_KERNEL, in_ch = CONV2_FILTERS;
    int ps = kd * kd * in_ch;
    elem_t mat[ps][out_ch];
    flatten_weights(out_ch, kd, in_ch, ps, (elem_t *)nlb_out_weights, (elem_t *)mat);
    print_array_2d("nlb_out_weights_flat", ps, out_ch, (elem_t *)mat);
  }

  return 0;
}
